+            return new ConditionChoice(choice.value(), choice.label());
+        }
+    }
+
+    /** 전략 카드 하나. <b>활성 전략만 실린다</b> — 비활성은 {@code selectable: false}가 아니라 목록에서 아예 빠진다. */
