+
+        public static Axis from(StrategyRegistryResult.AxisView view) {
+            return new Axis(
+                    view.name(),
+                    view.label(),
+                    view.description(),
+                    view.unit(),
+                    view.inputType().name(),
+                    view.choices() == null
+                            ? null
